      if (b.min.x < min.x) min.x = b.min.x;
      if (b.max.x > max.x) max.x = b.max.x;
      if (b.min.y < min.y) min.y = b.min.y;
      if (b.max.y > max.y) max.y = b.max.y;
    }
  }

  inline void offset (const Point &delta)
  {
    if (!empty ())
    {
      min.move (delta);
      max.move (delta);
    }
  }

