And `std_code_to_glyph`:
```cpp
inline unsigned int std_code_to_glyph (hb_codepoint_t code) const
{
  hb_codepoint_t sid = lookup_standard_encoding_for_sid (code);
  if (unlikely (sid == CFF_UNDEF_SID)) return 0;

  if (charset != &Null(Charset))
    return charset->get_glyph (sid, num_glyphs);
  else if ((topDict.CharsetOffset == ISOAdobeCharset) && (code <= 228)) return sid;
  return 0;
}
```

And `Charset::get_glyph` for format 1:
```cpp
inline hb_codepoint_t get_glyph (hb_codepoint_t sid, unsigned int num_glyphs) const
{
  if (format == 0)
    return u.format0.get_glyph (sid, num_glyphs);
  else if (format == 1)
    return u.format1.get_glyph (sid);// NO num_glyphs bounds!
  else
